import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val br = BufferedReader(InputStreamReader(System.in))
    val firstLine = br.readLine()?.split(" ")?.map { it.toInt() } ?: return
    val n = firstLine[0]
    val m = firstLine[1]

    val edges = mutableListOf<Pair<Int, Int>>()
    for (i in 0 until m) {
        val parts = br.readLine()?.split(" ")?.map { it.toInt() - 1 } ?: continue
        edges.add(parts[0] to parts[1])
    }

    if (m == 0) {
        println(0)
        return
    }

    // Since n <= 7, we can brute force assignment of colors (1..6) to vertices
    // Total assignments: 6^n, max 6^7 = 279936
    val maxColors = 6
    var maxDominoes = 0

    val totalAssignments = Math.pow(maxColors.toDouble(), n.toDouble()).toInt()

    // Pre-calculate domino pairs for each edge for a given assignment? 
    // We can just iterate all assignments.
    // Use an integer array to store color for each vertex (0..5 representing 1..6)
    val colors = IntArray(n)

    // We can iterate using a base-6 counter
    for (assignment in 0 until totalAssignments) {
        var x = assignment
        for (i in 0 until n) {
            colors[i] = x % maxColors
            x /= maxColors
        }

        val usedDominoes = BooleanArray(21) // Index: (a*6 + b) or map (a,b) with a<=b
        // Mapping domino (a,b) 1-based to index: (a-1)*6 + (b-1) - (a-1)*a/2? 
        // Simpler: since a,b in 1..6, a<=b, map to index: (a-1)*6 + (b-1) - (a-1)*a/2? 
        // Actually standard mapping: a,b in 0..5, a<=b. Index = a*6 + b - a*(a+1)/2. 
        // Let's just use a Set of Pairs or a boolean 2D array 6x6.
        val used = Array(6) { BooleanArray(6) }

        var count = 0
        for ((u, v) in edges) {
            val c1 = colors[u]
            val c2 = colors[v]
            val a = min(c1, c2)
            val b = max(c1, c2)
            if (!used[a][b]) {
                used[a][b] = true
                count++
            }
        }
        if (count > maxDominoes) maxDominoes = count
    }

    println(maxDominoes)
}
